def FGFIG(f):
    t, cap, who, mem = FG_PHOTOS[f]
    return (f'<figure class="hfig"><a href="{{P}}assets/images/{f}"><img src="{{P}}assets/images/{f}" alt="{t}" loading="lazy"></a>'
            f'<figcaption><strong>{t}.</strong> {cap}<span class="credit"><a href="{FG}{mem}">Photo: {who}, Find a Grave</a></span></figcaption></figure>')
def FGBLOCK(name, mem, facts, photos, conflict=""):
    h = f'<h3>{name}</h3>' if name else ''
    link = f'<p><a href="{FG}{mem}">Find a Grave memorial {mem.split("/")[0]}</a>. As given there (secondary; not checked against original records): {facts}</p>' if mem else ''
    figs = ('<div class="figs">' + "".join(FGFIG(f) for f in photos) + '</div>') if photos else ''
    return h + link + (FLAG(conflict) if conflict else '') + figs
FG_CREDITS = '<section id="findagrave-credits"><h2>Find a Grave Photo Credits</h2><p>These photographs belong to the Find a Grave contributors named, are stored on this site, and link to the memorial where each appears.</p><ul>' + "".join(
    f'<li><a href="{{P}}assets/images/{f}">{t}</a>. <a href="{FG}{mem}">Photo: {who}, Find a Grave</a></li>' for f, (t, cap, who, mem) in FG_PHOTOS.items()) + '</ul></section>'
_EXTRA0 = EXTRA
def EXTRA(path):
    out = _EXTRA0(path)
    if path in FG_PAGES:
        mem, facts, ph, cf = FG_PAGES[path]
        out += '{DIV}<section id="find-a-grave" class="gallery"><h2>Find a Grave</h2>' + FGBLOCK("", mem, facts, ph, cf) + '</section>'
    if path in FG_SECTIONS:
        out += '{DIV}<section id="find-a-grave" class="gallery"><h2>Find a Grave Memorials</h2>' + "".join(FGBLOCK(*b) for b in FG_SECTIONS[path]) + '</section>'
    if path == "sources.html": out += "{DIV}" + FG_CREDITS
    return out
